// This function is called when a single byte is received on the UART.
void testharness_PI_samv71rx( const asn1SccT_UInt8 * iInByte)
{
    static unsigned int itemCount = 0;
    static unsigned char items[1024];

    items[itemCount++] = (unsigned char)(*iInByte);
    itemCount &= 1023;
}


